import{z as A,x as s,o as l,c as m,q as i,j as n,D as E,d as t,s as d,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"色差与光源带宽","description":"","frontmatter":{"title":"色差与光源带宽","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/chromatic-bandwidth.md","filePath":"litho/chromatic-bandwidth.md","lastUpdated":1791413859000}'),B={name:"litho/chromatic-bandwidth.md"};function p(h,a,b,c,D,F){const r=s("Mermaid");return l(),m("div",null,[a[2]||(a[2]=i('<h1 id="色差与光源带宽" tabindex="-1">色差与光源带宽 <a class="header-anchor" href="#色差与光源带宽" aria-label="Permalink to &quot;色差与光源带宽&quot;">​</a></h1><div class="epigraph"><p>单色推导把 $n$ 和光瞳相位当成一个 $\\omega$ 上的数；准分子与 EUV 都有有限带宽，成像是许多单色空中像的强度叠加。</p><footer>—— 据 Mack 对激光带宽与色差的讨论；准分子线宽与 EUV 多层膜通带见公开光源 / 光学文献</footer></div><p><a href="/litho/strehl-ratio">上一课</a>（Strehl 比）。把单色光瞳相位收成 Zernike 系数。缺口是：第一课就声明过单色是零阶模型，真实光源不是 \\(\\delta(\\omega)\\)。折射率 \\(n(\\omega)\\)、镜头色散、EUV 多层膜反射通带，都会让 \\(P\\) 与最佳焦面随波长走。本课把有限带宽写成对单色像的非相干积分。其后进入产线判据课，本课仍不写 \\(k_1\\) 公式，也不引用未公开的机台色差残差表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的 \\(c_j\\) 是某一个真空波长上的拟合。玻璃（或氟化钙）的 \\(dn/d\\lambda\\) 让球差、离焦项随 \\(\\lambda\\) 变：纵向色差表现为最佳焦面移动，横向色差表现为倍率随 \\(\\lambda\\) 变。光源有宽度 \\(\\Delta\\lambda\\) 时，晶圆上的强度是各谱元空中像的加权和——等价于把 Bossung 沿焦轴再糊一次，NILS 掉。缺口因此是给「单色 TCC」加上光谱权重，而不是重讲 Zernike 基底。</p><p><span class="marginnote">「色差」就是不同「颜色」的光在镜头里走出的像不一样：折射率 \\(n\\) 随波长变，各谱元的焦点、倍率跟着错位。光刻的对策不是堆消色差透镜，而是直接把光源谱宽压窄，让「许多颜色」退化成「几乎一种颜色」。</span></p><p>时间相干长度 \\(\\propto\\lambda^2/\\Delta\\lambda\\) 与空间 \\(\\sigma\\) 不是同一个旋钮：带宽改的是轴向色差与相干长度，不改照明填充比。</p><h3 id="准分子与-euv-的带宽不是一类数" tabindex="-1">准分子与 EUV 的带宽不是一类数 <a class="header-anchor" href="#准分子与-euv-的带宽不是一类数" aria-label="Permalink to &quot;准分子与 EUV 的带宽不是一类数&quot;">​</a></h3><p>ArF 成像透镜是折射 / 折反射，色散敏感，所以注入锁定的准分子激光把带宽压到<strong>皮米量级</strong>（公开的线窄化激光指标以 pm、E95 或 FWHM 报）。EUV 没有玻璃透镜，色散机制换成多层膜反射率随 \\(\\lambda\\) 的通带：围绕 \\(13.5\\,\\mathrm{nm}\\) 的相对宽度约百分之二这一量级，是多层膜公开设计的通带，不是某台扫描机的内部秘密。等离子体发射可以更宽，镜子先当光谱滤波器。</p><p><span class="marginnote">不要把「EUV 很单色」写成物理事实。相对带宽比线窄化 ArF 宽得多；绝对波长短，色差通道换成膜系与抗蚀剂吸收，而不是 \\(dn/d\\lambda\\) 玻璃。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单色强度 \\(I(x;\\lambda)\\) 由该 \\(\\lambda\\) 的 \\(n\\)、\\(\\mathrm{NA}\\) 约定与 \\(P(\\lambda)\\) 计算。光源谱 \\(S(\\lambda)\\)（再乘光学通带）给出</p> \\[I_\\mathrm{poly}(x)=\\int S(\\lambda)\\,I(x;\\lambda)\\,d\\lambda. \\]<p>纵向色差主导时，这近似于对焦面做加权平均：带宽越宽，等效通过焦点的混合越重，等焦附近也可能被抹掉。激光线宽控制的工艺含义就是守住这根轴向糊。</p><p>横向色差让不同谱元的倍率微差，边缘变色、套刻色相关——扫描投影里通常被设计压到低于套刻预算，本课只指出通道存在。</p><h3 id="与-σ-分家" tabindex="-1">与 σ 分家 <a class="header-anchor" href="#与-σ-分家" aria-label="Permalink to &quot;与 σ 分家&quot;">​</a></h3><p>\\(\\sigma\\) 是光瞳填充，上一课序已经钉死。带宽不进 \\(S(\\mathbf{f})\\) 的半径，进的是对 \\(\\lambda\\) 的积分。把对比下降全部归咎于「\\(\\sigma\\) 太大」，会把色差误诊成照明。配方要同时写线宽（或 EUV 源谱 / 膜系通带）与 \\(\\sigma\\)。</p><p><span class="marginnote">公开讨论里，ArF 线宽收窄是为了镜头色差；收得过窄会碰到激光功率与频谱稳定性的工程边界。具体瓦数与某代 E95 验收值以厂商公开规格为准，本课不编造。</span></p>',18)),(l(),n(o,null,{default:E(()=>[d(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20MONO%5B%22%E5%8D%95%E8%89%B2%20I(x%3B%20%CE%BB)%22%5D%20--%3E%20INT%5B%22%E5%AF%B9%E8%B0%B1%20S(%CE%BB)%20%E7%A7%AF%E5%88%86%22%5D%0A%20%20DISP%5B%22n(%CE%BB)%20%2F%20%E8%86%9C%E7%B3%BB%E9%80%9A%E5%B8%A6%22%5D%20--%3E%20P%5B%22P(%CE%BB)%E3%80%81%E7%84%A6%E9%9D%A2%E9%9A%8F%20%CE%BB%22%5D%0A%20%20P%20--%3E%20MONO%0A%20%20INT%20--%3E%20POLY%5B%22%E5%A4%8D%E8%89%B2%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%0A%20%20POLY%20--%3E%20NILS%5B%22NILS%20%E5%86%8D%E6%8E%89%E4%B8%80%E6%88%AA%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"第一课的相位 \\(k_0\\int n\\,ds\\) 在 \\(n=n(\\lambda)\\) 时对每个谱元不同。镜头把这一差收成 Zernike 的 \\(\\lambda\\) 导数，最显眼的是离焦项随 \\(\\lambda\\) 走。谱积分之后，相干交叉项在不同 \\(\\lambda\\) 上对不齐，等效对比下降。这与部分相干的源点积分同构：一个对方向非相干相加，一个对频率非相干相加。",-1)),a[5]||(a[5]=e("p",null,"上一张图画的是复色像如何由谱积分构成；这里补一张对比图，回答另一个问题：ArF 与 EUV 的色差为什么走的是两条不同的通道、各自用什么手段压。",-1)),(l(),n(o,null,{default:E(()=>[d(r,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARF%5B%22ArF%20193%20nm%22%5D%20--%3E%20GL%5B%22%E7%8E%BB%E7%92%83%20%2F%20CaF2%20%E6%8A%98%E5%B0%84%EF%BC%9Adn%2Fd%CE%BB%22%5D%0A%20%20GL%20--%3E%20FOC%5B%22%E6%9C%80%E4%BD%B3%E7%84%A6%E9%9D%A2%E9%9A%8F%20%CE%BB%20%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20GL%20--%3E%20FIX1%5B%22%E8%A7%A3%E6%B3%95%EF%BC%9A%E7%BA%BF%E7%AA%84%E5%8C%96%E6%BF%80%E5%85%89%EF%BC%88%E7%9A%AE%E7%B1%B3%E9%87%8F%E7%BA%A7%EF%BC%89%22%5D%0A%20%20EUV%5B%22EUV%2013.5%20nm%22%5D%20--%3E%20ML%5B%22Mo%2FSi%20%E5%A4%9A%E5%B1%82%E8%86%9C%E9%80%9A%E5%B8%A6%E7%BA%A6%202%25%22%5D%0A%20%20ML%20--%3E%20FILT%5B%22%E9%95%9C%E5%AD%90%E5%BD%93%E5%85%89%E8%B0%B1%E6%BB%A4%E6%B3%A2%E5%99%A8%22%5D%0A%20%20ML%20--%3E%20FIX2%5B%22%E8%A7%A3%E6%B3%95%EF%BC%9A%E8%86%9C%E7%B3%BB%E8%AE%BE%E8%AE%A1%E5%AE%9A%E9%80%9A%E5%B8%A6%22%5D%0A%20%20FOC%20--%3E%20SAME%5B%22%E9%83%BD%E6%94%B6%E6%88%90%EF%BC%9A%E5%AF%B9%E8%B0%B1%E5%8A%A0%E6%9D%83%E7%A7%AF%E5%88%86%E7%9A%84%E5%A4%8D%E8%89%B2%E5%83%8F%22%5D%0A%20%20FILT%20--%3E%20SAME%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">直觉类比：复色成像像一群步调稍不齐的人齐唱——每个波长单独成像都还行，叠在一起波峰波谷对不齐，总响度（对比度）就掉。谱宽越宽错位越大；「线窄化」就是把合唱队练成几乎同一步调。</span></p><p>EUV 多层膜的通带还调制各谱元的权重，并与掩模 3D 的光谱响应纠缠。本课停在「必须积分」，把膜系结构留给多层镜课。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到单色模型，默认它是零阶；工艺讨论带宽时，空中像指谱积分后的 \\(I_\\mathrm{poly}\\)。Zernike 表必须声明波长。产线 CD 公式用标称 \\(\\lambda\\)，不把 \\(\\Delta\\lambda\\) 写进 \\(k_1\\) 的定义里——带宽的税打进对比与焦深余量。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供未公开的 ASML 镜头色差系数，不用内部 E95 表冒充物理常数。准分子「皮米量级」、EUV 多层膜「约 2% 通带」只是公开量级，设计值随膜系与激光器型号变。也不要把带宽当成免费的焦深扩展（focus drilling 是后课有意扫焦，与源谱是两件事）。</p><p><span class="marginnote">数字感受两类带宽的差距：ArF 线窄化激光的 E95 在皮米量级，相对带宽约 \\(10^{-6}\\)；EUV 多层膜通带约 2%，相对带宽约 \\(2 \\times 10^{-2}\\)——差四五个数量级。但 EUV 没有玻璃可色散，镜子直接当滤波器，两套机制各按各的账。</span></p><p>\\(\\sigma\\) 定义不改。矢量 TE/TM 对每个 \\(\\lambda\\) 各做一次，再积分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有限带宽 = 单色空中像按谱加权叠加；纵向色差等效糊焦。</li><li>ArF 靠线窄化（皮米量级）压玻璃色散；EUV 靠多层膜通带（约 2% 量级）滤波。</li><li>带宽不是 \\(\\sigma\\)；一个改光谱，一个改空间填充。</li><li>Zernike 系数随 \\(\\lambda\\) 变，表上要写波长。</li><li>本课不编造未公开机台色差数。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>；准分子线宽与 EUV 膜系通带的公开讨论。</li></ul>',10))])}const f=A(B,[["render",p]]);export{C as __pageData,f as default};
